import React, { useContext, useEffect, useState } from 'react';
//
import { useQuery } from '@tanstack/react-query'
import {
    Grid,
    AppBar,
    Toolbar,
    Typography,
    Box,
    TextField,
    Autocomplete,
    Tabs,
    Tab,
    Button,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions
} from '@mui/material'
//
import NearMeIcon from '@mui/icons-material/NearMe'
import MapIcon from '@mui/icons-material/Map'
import IconButton from '@mui/material/IconButton'
import Tooltip from '@mui/material/Tooltip'
import SaveIcon from '@mui/icons-material/Save'
import CloseIcon from '@mui/icons-material/Close'
//
import { GeneralCtx } from '../../contextos/GeneralContext';
import campoNaranjos from '../../../src/imagenes/campo-naranjos.png'

import { DataGrid } from '@mui/x-data-grid'

import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { LeerCamposSocio, LeerCoordenadasSigpac, LeerCampoClasificacion, LeerCampoRevision, CrearCampoRevision } from '../../servicios/Campos'
import { leerSocios } from '../../servicios/Socios'


export default function CamposSocioPagina() {
    const [hayError, setHayError] = useState(false);
    const [mensajeError, setMensajeError] = useState('');
    //
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    //
    const [campos, setCampos] = useState([]);
    const [filterModel, setFilterModel] = useState({ items: [] });
    //
    const [inputSocio, setInputSocio] = useState('')
    const [socios, setSocios] = useState([]);
    const [socioSeleccionado, setSocioSeleccionado] = useState(null);
    //
    const [filaRuta, setFilaRuta] = useState(null)
    const [tabDetalle, setTabDetalle] = useState(0)
    //
    const [usuario, setUsuario] = useState(null)
    //
    const codsocio = socioSeleccionado?.codsocio
    //
    const [abrirRevision, setAbrirRevision] = useState(false)

    const [datosRevision, setDatosRevision] = useState({
        fecha: new Date().toISOString().slice(0, 10),
        tecnico: '',
        tecnicoId: 0,
        observac: ''
    })
    //
    const { getSession } = useContext(GeneralCtx);




    const formatearCampos = (data) => {
        return data.map(c => ({
            codcampo: c.codcampo ?? c.nrocampo,
            nomsocio: c.nomsocio || '',
            nrocampo: c.nrocampo || '',
            codsocio: c.codsocio || '',
            poligono: c.poligono || '',
            parcela: c.parcela || '',
            supsigpa: c.supsigpa ?? 0,
            nroarbol: c.nroarbol ?? 0,
            anoplant: c.anoplant ?? 0,
            latitud: c.latitud || '',
            longitud: c.longitud || '',
            nomvarie: c.nomvarie || '',
            nomparti: c.nomparti || '',
            codpobla: c.codpobla || '',
            codsigpa: c.codsigpa || '',
            recintos: c.recintos || '',
            nombrepueblo: c.nombrepueblo || ''
        }))
    }

    const queryCampos = useQuery({
        queryKey: ['campos-socio', codsocio],
        queryFn: async () => {
            try {
                const data = await LeerCamposSocio(codsocio)

                if (data) {
                    const camposLimpios = formatearCampos(data)
                    setCampos(camposLimpios)
                    return camposLimpios
                }

                return []
            } catch (error) {
                console.error('Error en queryCampos:', error)
                setMensajeError(MensajeError(error))
                setHayError(true)
                throw error
            }
        },
        enabled: !!codsocio,
        refetchOnWindowFocus: true,
    })

    const querySocios = useQuery({
        queryKey: ['socios-busqueda', inputSocio],
        queryFn: async () => {
            try {
                const data = await leerSocios(inputSocio)
                setSocios(data)
                return data
            } catch (error) {
                console.error('Error en queryFn:', error);
                setMensajeError(MensajeError(error));
                setHayError(true);
                throw error; // necesario para que React Query registre el error
            }
        },
        enabled: inputSocio.length >= 3,
    })

    const localeTextES = {
        noRowsLabel: 'No hay campos',
        noResultsOverlayLabel: 'No se encontraron resultados',
        errorOverlayDefaultLabel: 'Ha ocurrido un error.',
        footerRowSelected: (count) =>
            count !== 1
                ? `${count.toLocaleString()} filas seleccionadas`
                : `${count.toLocaleString()} fila seleccionada`,
        MuiTablePagination: {
            labelRowsPerPage: 'Filas por página:',
            labelDisplayedRows: ({ from, to, count }) =>
                `${from}–${to} de ${count !== -1 ? count : `más de ${to}`}`,
        },
    }

    const abrirSigpac = (fila) => {
        if (!fila) return

        const provincia = String(fila.codpobla || '').substring(0, 2)
        const municipio = fila.codsigpa
        const agregado = 0
        const zona = 0
        const poligono = fila.poligono
        const parcela = fila.parcela
        const recinto = fila.recintos

        const url = `https://sigpac.mapa.es/fega/visor/?provincia=${provincia}&municipio=${municipio}&agregado=${agregado}&zona=${zona}&poligono=${poligono}&parcela=${parcela}&recinto=${recinto}`

        //setUrlSigpac(url)

        window.open(url, '_blank')
    }



    const abrirNavegacionGoogle = async (fila) => {
        try {
            const provincia = String(fila.codpobla || '').substring(0, 2)
            const municipio = fila.codsigpa
            const agregado = 0
            const zona = 0
            const poligono = fila.poligono
            const parcela = fila.parcela
            const recinto = fila.recintos

            let data = await LeerCoordenadasSigpac(provincia, municipio, agregado, zona, poligono, parcela, recinto)

            console.log('Coordenadas obtenidas:', data)

            const wkt = data[0].wkt

            const [longitud, latitud] = wkt
                .replace('POINT(', '')
                .replace(')', '')
                .split(' ')
                .map(Number)

            console.log({ latitud, longitud })

            const destino = `${Number(latitud)}, ${Number(longitud)}`

            const url = `https://www.google.com/maps/dir/?api=1&destination=${destino}&travelmode=driving`

            window.open(url, '_blank')


        } catch (e) {
            setMensajeError('Faltan coordenadas para iniciar la navegación')
            setHayError(true)
            setFilaRuta(null)
            return
        }
    }

    const getCampoClasificacion = async (fila) => {
        try {
            if (!fila) {
                throw new Error('Faltan datos para obtener la clasificación del campo')
            }

            let data = await LeerCampoClasificacion(fila.codcampo)

            let revision = await LeerCampoRevision(fila.codcampo)

            setFilaRuta({
                ...fila,
                clasificacion: data.clasificacion || [],
                resumen: data.resumen || {},
                revision: revision || []
            })

            return data
        } catch (e) {
            setMensajeError('Error al recuperar la clasificacion del campo')
            setHayError(true)
            setFilaRuta(null)
            return
        }
    }

    const clasificacion = filaRuta?.clasificacion || []

    const revision = filaRuta?.revision || []

    const totalKilosClasificados = clasificacion.reduce(
        (total, item) => total + Number(item.kilos || 0),
        0
    )

    const resumen = filaRuta?.resumen || {}

    const formatoKilos = (valor) =>
        new Intl.NumberFormat('es-ES', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
            useGrouping: true,
        }).format(Number(valor || 0))

    const formatoFecha = (valor) => {
        if (!valor) return ''

        return new Date(valor).toLocaleDateString('es-ES', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
        })
    }

    const columns = [
        {
            field: 'nrocampo',
            headerName: 'Campo',
            width: 90,
            headerClassName: 'bold-header',
            cellClassName: 'bold-cell',
        },
        {
            field: 'nomvarie',
            headerName: 'Variedad',
            flex: 0.3,
        },
        {
            field: 'nomparti',
            headerName: 'Partida',
            flex: 0.5,
        },
        {
            field: 'nombrepueblo',
            headerName: 'Municipio',
            flex: 0.2,
        },
        {
            field: 'poligono',
            headerName: 'Pol.',
            width: 80,
            align: 'right',
            headerAlign: 'right',
        },
        {
            field: 'parcela',
            headerName: 'Parcela',
            width: 100,
            align: 'right',
            headerAlign: 'right',
        },
        {
            field: 'nroarbol',
            headerName: 'Árboles',
            width: 90,
            align: 'right',
            headerAlign: 'right',
        },
        {
            field: 'anoplant',
            headerName: 'A. Plan.',
            width: 90,
            align: 'right',
            headerAlign: 'right',
        },
        {
            field: 'supsigpa',
            headerName: 'Has',
            width: 90,
            align: 'right',
            headerAlign: 'right',
            renderCell: (params) => {
                const valor = Number(params.value ?? 0)

                return valor.toLocaleString('es-ES', {
                    minimumFractionDigits: 4,
                    maximumFractionDigits: 4,
                })
            },
        },
        {
            field: 'hanegadas',
            headerName: 'Hgdas',
            width: 90,
            align: 'right',
            headerAlign: 'right',
            valueGetter: (value, row) => Number(row.supsigpa ?? 0) * 12,
            renderCell: (params) => {
                return Number(params.value).toLocaleString('es-ES', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2,
                })
            },
        },
        {
            field: 'acciones',
            headerName: '',
            width: 110,
            sortable: false,
            filterable: false,
            align: 'center',
            headerAlign: 'center',
            renderCell: (params) => (
                <Box sx={{ display: 'flex', gap: 0.5 }}>
                    <Tooltip title="Navegar">
                        <IconButton
                            size="small"
                            color="primary"
                            onClick={(event) => {
                                event.stopPropagation()
                                abrirNavegacionGoogle(params.row)
                            }}
                        >
                            <NearMeIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>

                    <Tooltip title="SIGPAC">
                        <IconButton
                            size="small"
                            color="success"
                            onClick={(event) => {
                                event.stopPropagation()
                                abrirSigpac(params.row)
                            }}
                        >
                            <MapIcon fontSize="small" />
                        </IconButton>
                    </Tooltip>
                </Box>
            ),
        }
    ]

    const columnsRevision = [
        {
            field: 'numlinea',
            headerName: 'Línea',
            width: 90,
            align: 'right',
            headerAlign: 'right',
            renderCell: (params) => (
                <Box
                    sx={{
                        py: 0.5
                    }}
                >
                    {params.value}
                </Box>
            )

        },
        {
            field: 'fecha',
            headerName: 'Fecha',
            width: 140,
            renderCell: (params) => (
                <Box
                    sx={{
                        py: 0.5
                    }}
                >
                    {formatoFecha(params.value)}
                </Box>
            )
        },
        {
            field: 'tecnico',
            headerName: 'Técnico',
            flex: 0.5,
            renderCell: (params) => (
                <Box
                    sx={{
                        py: 0.5
                    }}
                >
                    {params.value}
                </Box>
            )
        },
        {
            field: 'observac',
            headerName: 'Observaciones',
            flex: 1.5,
            renderCell: (params) => (
                <Box
                    sx={{
                        whiteSpace: 'pre-line',
                        py: 0.5,
                        lineHeight: 1.4
                    }}
                >
                    {params.value}
                </Box>
            )
        },
    ]

    useEffect(() => {
        const session = getSession();

        console.log(session);

        if (session) {
            setUsuario(session.usuario);
        }
    }, []);


    return (
        <>
            <MenuLateral>

                <AppBar
                    id="imagen"
                    position="static"
                    sx={{
                        mb: 2,
                        backgroundColor: '#1d4d75',
                    }}
                >
                    <Toolbar sx={{ gap: 2 }}>
                        <Typography variant="h6">
                            Socio
                        </Typography>

                        <Autocomplete
                            options={socios}
                            value={socioSeleccionado}
                            inputValue={inputSocio}
                            loading={querySocios.isLoading}
                            onInputChange={(event, newInputValue) => {
                                setInputSocio(newInputValue)

                                if (newInputValue.length < 3) {
                                    setSocios([])
                                }
                            }}
                            onChange={(event, newValue) => {
                                setSocioSeleccionado(newValue)
                            }}
                            getOptionLabel={(option) =>
                                option ? `${option.codsocio} - ${option.nomsocio}` : ''
                            }
                            isOptionEqualToValue={(option, value) =>
                                option.codsocio === value.codsocio
                            }
                            noOptionsText={
                                inputSocio.length < 3
                                    ? 'Escribe al menos 3 caracteres'
                                    : 'No hay socios'
                            }
                            sx={{
                                width: 450,
                                backgroundColor: 'white',
                                borderRadius: 1
                            }}
                            renderInput={(params) => (
                                <TextField
                                    {...params}
                                    placeholder="Buscar socio"
                                    size="small"
                                />
                            )}
                        />
                        <Typography variant='h6'>
                            Nº Rea: {socioSeleccionado?.nrorea}
                        </Typography>

                        <Typography variant='h6'>
                            Nº Siex: {socioSeleccionado?.nrosiex}
                        </Typography>

                        <Typography variant='h6'>
                            Ref. Externa: {socioSeleccionado?.nroasociado}
                        </Typography>

                        <Box sx={{ flexGrow: 1 }} />


                        <Typography variant="h6">
                            Total campos: {campos.length}
                        </Typography>
                    </Toolbar>
                </AppBar>

                <Grid item xs={12} sx={{ height: '40vh', width: '100%', overflow: 'hidden' }}>
                    <DataGrid
                        rows={campos}
                        columns={columns}
                        loading={queryCampos.isLoading}
                        filterModel={filterModel}
                        onFilterModelChange={(newModel) => setFilterModel(newModel)}
                        getRowId={(row) => row.codcampo}
                        onRowDoubleClick={(params) => abrirSigpac(params.row)}
                        onRowClick={(params) => getCampoClasificacion(params.row)}
                        localeText={localeTextES}
                        rowHeight={30}
                        headerHeight={60}
                        sx={{
                            borderRadius: 2,
                            boxShadow: 10,
                            border: 'none',

                            height: '100%',

                            '.MuiDataGrid-virtualScroller': {
                                overflowY: 'auto !important',
                                overflowX: 'auto !important',
                            },

                            '.MuiDataGrid-columnHeaders': {
                                color: '#1723d4 !important',
                                fontSize: 20,
                                fontWeight: '900',
                                borderBottom: '3px solid #90caf9',
                            },

                            '.MuiDataGrid-cell': {
                                fontSize: 15,
                                color: '#111',
                            },

                            '.MuiDataGrid-row': {
                                backgroundColor: '#f9f9f9',
                                '&:nth-of-type(even)': {
                                    backgroundColor: '#e3f2fd',
                                },
                            },

                            '.MuiDataGrid-row:hover': {
                                backgroundColor: '#bbdefb',
                            },

                            '.MuiDataGrid-row.Mui-selected': {
                                backgroundColor: '#90caf9 !important',
                                color: '#fff',
                            },

                            '.bold-header': {
                                fontWeight: '900',
                                color: '#010107ff',
                            },

                            '.bold-cell': {
                                fontWeight: 'bold',
                                color: '#000',
                            },

                            '.MuiDataGrid-overlay': {
                                color: '#fff',
                                backgroundColor: 'transparent',
                                fontSize: 18,
                                fontWeight: 'bold',
                            },
                        }}
                    />
                </Grid>

                {filaRuta && (
                    <Box sx={{ width: '100%', mt: 2 }}>
                        <Tabs
                            value={tabDetalle}
                            onChange={(event, newValue) => setTabDetalle(newValue)}
                            sx={{
                                backgroundColor: '#fff',
                                borderRadius: 1,
                                boxShadow: 3,
                                mb: 2,
                            }}
                        >
                            <Tab label="Datos de recolección" />
                            <Tab label="Revisiones" />
                        </Tabs>

                        {tabDetalle === 0 && (
                            <>
                                <Grid item xs={12} sx={{ width: '100%', mt: 1 }}>
                                    <Grid item xs={12} sx={{ width: '100%', mt: 1 }}>
                                        <Box
                                            sx={{
                                                p: 2,
                                                borderRadius: 2,
                                                boxShadow: 6,
                                                backgroundColor: '#fff',
                                            }}
                                        >
                                            <Typography
                                                variant="h6"
                                                sx={{
                                                    mb: 2,
                                                    fontWeight: 'bold',
                                                    color: '#1723d4',
                                                }}
                                            >
                                                DATOS DE RECOLECCIÓN
                                            </Typography>

                                            <Grid container spacing={2}>


                                                <Grid item xs={12}>
                                                    <Box
                                                        sx={{
                                                            display: 'grid',
                                                            gridTemplateColumns: 'repeat(4, 1fr)',
                                                            gridAutoRows: '48px',
                                                            borderRadius: 2,
                                                            boxShadow: 6,
                                                            overflow: 'hidden',
                                                            backgroundColor: '#fff',
                                                            color: '#000',
                                                        }}
                                                    >
                                                        <Box sx={{ px: 1.5, display: 'flex', alignItems: 'center', fontWeight: 'bold', backgroundColor: '#e3f2fd' }}>
                                                            KGS RECOLECTADOS
                                                        </Box>

                                                        <Box sx={{ px: 1.5, display: 'flex', alignItems: 'center', fontWeight: 'bold', backgroundColor: '#e3f2fd' }}>
                                                            KGS. PDTES. CLASIFICAR
                                                        </Box>

                                                        <Box sx={{ px: 1.5, display: 'flex', alignItems: 'center', fontWeight: 'bold', backgroundColor: '#e3f2fd' }}>
                                                            KGS. CLASIFICADOS
                                                        </Box>

                                                        <Box sx={{ px: 1.5, display: 'flex', alignItems: 'center', fontWeight: 'bold', backgroundColor: '#e3f2fd' }}>
                                                            FECHAS RECOLECCIÓN
                                                        </Box>

                                                        <Box
                                                            sx={{
                                                                px: 1.5,
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                justifyContent: 'flex-end',
                                                                textAlign: 'right',
                                                                borderTop: '1px solid #ddd',
                                                                paddingRight: 36,
                                                            }}
                                                        >
                                                            {formatoKilos(resumen.kilos_totales_recolectados)}
                                                        </Box>

                                                        <Box
                                                            sx={{
                                                                px: 1.5,
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                justifyContent: 'flex-end',
                                                                textAlign: 'right',
                                                                borderTop: '1px solid #ddd',
                                                                paddingRight: 33,
                                                            }}
                                                        >
                                                            {formatoKilos(resumen.kilos_pendientes_clasificar)}
                                                        </Box>

                                                        <Box
                                                            sx={{
                                                                px: 1.5,
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                justifyContent: 'flex-end',
                                                                textAlign: 'right',
                                                                borderTop: '1px solid #ddd',
                                                                paddingRight: 37,
                                                            }}
                                                        >
                                                            {formatoKilos(resumen.kilos_clasificados)}
                                                        </Box>

                                                        <Box
                                                            sx={{
                                                                px: 1.5,
                                                                borderTop: '1px solid #ddd',
                                                                display: 'flex',
                                                                flexDirection: 'column',
                                                                justifyContent: 'center',
                                                            }}
                                                        >
                                                            <span>
                                                                <strong>Primera:</strong> {formatoFecha(resumen.primera_fecha_recoleccion)}
                                                            </span>

                                                            <span>
                                                                <strong style={{ paddingRight: 6 }}>Última:</strong> {formatoFecha(resumen.ultima_fecha_recoleccion)}
                                                            </span>
                                                        </Box>
                                                    </Box>
                                                </Grid>
                                            </Grid>
                                        </Box>
                                    </Grid>
                                </Grid>

                                <Box
                                    sx={{
                                        mt: 2,
                                        px: { xs: 1, md: 2 },
                                        display: 'flex',
                                        justifyContent: 'center',
                                    }}
                                >
                                    <Box
                                        sx={{
                                            width: '100%',
                                            maxWidth: 1400,
                                            display: 'grid',
                                            gridTemplateColumns: {
                                                xs: '1fr',
                                                md: '1fr 1fr',
                                            },
                                            gap: 2,
                                            alignItems: 'start',
                                        }}
                                    >
                                        <Box sx={{ width: '100%' }}>
                                            <Typography
                                                variant="subtitle1"
                                                sx={{
                                                    mb: 1,
                                                    fontWeight: 'bold',
                                                    color: '#1723d4',
                                                }}
                                            >
                                                CLASIFICACIÓN
                                            </Typography>

                                            <Box
                                                sx={{
                                                    maxHeight: 500,
                                                    overflowY: 'auto',
                                                    border: '1px solid #ddd',
                                                    borderRadius: 1,
                                                    boxShadow: 6,
                                                    backgroundColor: 'rgba(255,255,255,0.92)',
                                                }}
                                            >
                                                <Box
                                                    sx={{
                                                        display: 'grid',
                                                        gridTemplateColumns: '1fr 100px 130px',
                                                        color: '#111',
                                                        fontSize: 15,
                                                        fontWeight: 500,
                                                    }}
                                                >
                                                    <Box
                                                        sx={{
                                                            p: 1,
                                                            fontWeight: 'bold',
                                                            backgroundColor: '#e3f2fd',
                                                            position: 'sticky',
                                                            top: 0,
                                                            zIndex: 1,
                                                        }}
                                                    >
                                                        CALIDAD
                                                    </Box>

                                                    <Box
                                                        sx={{
                                                            p: 1,
                                                            fontWeight: 'bold',
                                                            backgroundColor: '#e3f2fd',
                                                            textAlign: 'right',
                                                            position: 'sticky',
                                                            top: 0,
                                                            zIndex: 1,
                                                        }}
                                                    >
                                                        KILOS
                                                    </Box>

                                                    <Box
                                                        sx={{
                                                            p: 1,
                                                            fontWeight: 'bold',
                                                            backgroundColor: '#e3f2fd',
                                                            textAlign: 'right',
                                                            position: 'sticky',
                                                            top: 0,
                                                            zIndex: 1,
                                                        }}
                                                    >
                                                        %
                                                    </Box>

                                                    {clasificacion.map((item) => {
                                                        const kilos = Number(item.kilos || 0)

                                                        const porcentaje =
                                                            totalKilosClasificados > 0
                                                                ? (kilos / totalKilosClasificados) * 100
                                                                : 0

                                                        return (
                                                            <React.Fragment key={item.codcalid}>
                                                                <Box
                                                                    sx={{
                                                                        p: 1,
                                                                        borderTop: '1px solid #ddd',
                                                                    }}
                                                                >
                                                                    {item.calidad}
                                                                </Box>

                                                                <Box
                                                                    sx={{
                                                                        p: 1,
                                                                        borderTop: '1px solid #ddd',
                                                                        textAlign: 'right',
                                                                    }}
                                                                >
                                                                    {formatoKilos(kilos)}
                                                                </Box>

                                                                <Box
                                                                    sx={{
                                                                        p: 1,
                                                                        borderTop: '1px solid #ddd',
                                                                        textAlign: 'right',
                                                                    }}
                                                                >
                                                                    {porcentaje.toLocaleString('es-ES', {
                                                                        minimumFractionDigits: 2,
                                                                        maximumFractionDigits: 2,
                                                                    })}
                                                                </Box>
                                                            </React.Fragment>
                                                        )
                                                    })}

                                                    <Box
                                                        sx={{
                                                            p: 1,
                                                            borderTop: '2px solid #999',
                                                            fontWeight: 'bold',
                                                            backgroundColor: '#f5f5f5',
                                                        }}
                                                    >
                                                        TOTAL
                                                    </Box>

                                                    <Box
                                                        sx={{
                                                            p: 1,
                                                            borderTop: '2px solid #999',
                                                            fontWeight: 'bold',
                                                            backgroundColor: '#f5f5f5',
                                                            textAlign: 'right',
                                                        }}
                                                    >
                                                        {formatoKilos(totalKilosClasificados)}
                                                    </Box>

                                                    <Box
                                                        sx={{
                                                            p: 1,
                                                            borderTop: '2px solid #999',
                                                            fontWeight: 'bold',
                                                            backgroundColor: '#f5f5f5',
                                                            textAlign: 'right',
                                                        }}
                                                    >
                                                        100,00
                                                    </Box>
                                                </Box>
                                            </Box>
                                        </Box>

                                        <Box
                                            sx={{
                                                width: '100%',
                                                height: 500,
                                                mt: 4.1,
                                                borderRadius: 1,
                                                boxShadow: 6,
                                                backgroundImage: `url(${campoNaranjos})`,
                                                backgroundRepeat: 'no-repeat',
                                                backgroundPosition: 'center',
                                                backgroundSize: 'cover',
                                                opacity: 0.32,
                                                filter: 'blur(1px)',
                                            }}
                                        />
                                    </Box>
                                </Box>
                            </>
                        )}

                        {tabDetalle === 1 && (
                            <Box
                                sx={{
                                    p: 2,
                                    borderRadius: 2,
                                    boxShadow: 6,
                                    backgroundColor: '#fff',
                                    color: '#000',
                                }}
                            >
                                <Box
                                    sx={{
                                        display: 'flex',
                                        justifyContent: 'space-between',
                                        alignItems: 'center',
                                        mb: 2,
                                    }}
                                >
                                    <Typography
                                        variant="h6"
                                        sx={{
                                            fontWeight: 'bold',
                                            color: '#1723d4',
                                        }}
                                    >
                                        REVISIONES DEL CAMPO
                                    </Typography>

                                    <Button
                                        variant="contained"
                                        size="small"
                                        onClick={() => {
                                            setDatosRevision({
                                                fecha: new Date().toISOString().slice(0, 10),
                                                tecnico: usuario?.nomusu || '',
                                                tecnicoId:  usuario?.codusu || 0,
                                                observac: ''
                                            })

                                            setAbrirRevision(true)
                                        }}
                                    >
                                        Añadir revisión
                                    </Button>
                                </Box>

                                <Box sx={{ height: 350, width: '100%' }}>
                                    <DataGrid
                                        rows={revision}
                                        columns={columnsRevision}
                                        getRowId={(row) =>
                                            row.id || `${row.codcampo}-${row.numlinea}`
                                        }
                                        localeText={localeTextES}
                                        getRowHeight={() => 'auto'}

                                        sx={{
                                            borderRadius: 2,
                                            boxShadow: 4,


                                            '.MuiDataGrid-columnHeaders': {
                                                color: '#1723d4 !important',
                                                fontSize: 16,
                                                fontWeight: '900',
                                                borderBottom: '3px solid #90caf9'
                                            },
                                            '& .MuiDataGrid-row': {
                                                maxHeight: 'none !important'
                                            },

                                            '.MuiDataGrid-row:nth-of-type(even)': {
                                                backgroundColor: '#e3f2fd',
                                            },

                                            '.MuiDataGrid-row:hover': {
                                                backgroundColor: '#bbdefb',
                                            },
                                            '& .MuiDataGrid-cell': {
                                                fontSize: 14,
                                                color: '#111',
                                                whiteSpace: 'normal !important',
                                                lineHeight: '1.4 !important',
                                                alignItems: 'flex-start',

                                            }
                                        }}
                                    />
                                </Box>
                            </Box>
                        )}
                    </Box>
                )}
                <Dialog
                    open={abrirRevision}
                    onClose={() => setAbrirRevision(false)}
                    maxWidth="md"
                    fullWidth
                >
                    <DialogTitle sx={{ fontWeight: 'bold', color: '#1723d4' }}>
                        Nueva revisión del campo
                    </DialogTitle>

                    <DialogContent dividers>
                        <Grid container spacing={2} sx={{ mt: 0.5 }}>
                            <Grid item xs={12} md={6}>
                                <TextField
                                    label="Fecha"
                                    type="date"
                                    value={datosRevision.fecha}
                                    fullWidth
                                    InputLabelProps={{ shrink: true }}
                                    onChange={(e) =>
                                        setDatosRevision({
                                            ...datosRevision,
                                            fecha: e.target.value
                                        })
                                    }
                                />
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <TextField
                                    label="Técnico"
                                    value={datosRevision.tecnico}
                                    fullWidth
                                    InputProps={{ readOnly: true }}
                                    sx={{
                                        '& .MuiInputBase-input': {
                                            backgroundColor: '#f5f5f5',
                                            cursor: 'not-allowed'
                                        }
                                    }}
                                />
                            </Grid>

                            <Grid item xs={12}>
                                <TextField
                                    label="Observaciones"
                                    value={datosRevision.observac}
                                    multiline
                                    rows={5}
                                    fullWidth
                                    autoFocus
                                    onChange={(e) =>
                                        setDatosRevision({
                                            ...datosRevision,
                                            observac: e.target.value
                                        })
                                    }
                                />
                            </Grid>
                        </Grid>
                    </DialogContent>

                    <DialogActions sx={{ px: 3, py: 2 }}>
                        <Button
                            variant="outlined"
                            color="inherit"
                            startIcon={<CloseIcon />}
                            onClick={() => setAbrirRevision(false)}
                        >
                            Cancelar
                        </Button>

                        <Button
                            variant="contained"
                            startIcon={<SaveIcon />}
                            onClick={async () => {
                                try {
                                    const revisionActual = filaRuta.revision || []

                                    const siguienteNumLinea =
                                        revisionActual.length === 0
                                            ? 1
                                            : Math.max(
                                                ...revisionActual.map(
                                                    r => Number(r.numlinea || 0)
                                                )
                                            ) + 1

                                    await CrearCampoRevision({
                                        codcampo: filaRuta.codcampo,
                                        numlinea: siguienteNumLinea,
                                        fecha: datosRevision.fecha,
                                        tecnico: datosRevision.tecnico,
                                        tecnicoId: datosRevision.tecnicoId,
                                        observac: datosRevision.observac
                                    })

                                    const revisionRecargada =
                                        await LeerCampoRevision(filaRuta.codcampo)

                                    setFilaRuta({
                                        ...filaRuta,
                                        revision: revisionRecargada || []
                                    })

                                    setAbrirRevision(false)
                                } catch (error) {
                                    setMensajeError(MensajeError(error))
                                    setHayError(true)
                                }
                            }}
                        >
                            Guardar
                        </Button>
                    </DialogActions>
                </Dialog>
                <ErrorGeneral
                    hayError={hayError}
                    mensajeError={mensajeError}
                    cerrarError={() => setHayError(false)}
                />
            </MenuLateral >
        </>
    )
}